"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Slot } from "../lib/slot";
import { Icon } from "../icons/icon";
import { useShell } from "./app-shell";

export interface SidebarProps extends React.HTMLAttributes<HTMLElement> {
  /** Verbergt de inklapknop onderaan. */
  hideCollapse?: boolean;
  /**
   * "surface" volgt de achtergrond van de app (standaard).
   * "inverted" geeft een donkere, teal-getinte rail — ook in lichtmodus.
   */
  tone?: "surface" | "inverted";
}

/** Sidebar — vaste navigatiekolom; op mobiel een uitschuifbaar paneel. */
export const Sidebar = React.forwardRef<HTMLElement, SidebarProps>(function Sidebar(
  { hideCollapse, tone = "surface", className, children, ...rest },
  ref
) {
  const { collapsed, setCollapsed, mobileOpen, setMobileOpen } = useShell();

  return (
    <aside
      ref={ref}
      className={cn("pxui-sidebar", mobileOpen && "pxui-sidebar-open", className)}
      data-collapsed={collapsed ? "" : undefined}
      data-tone={tone === "inverted" ? "inverted" : undefined}
      {...rest}
    >
      <button
        type="button"
        className="pxui-sidebar-mobile-close"
        aria-label="Menu sluiten"
        onClick={() => setMobileOpen(false)}
      >
        <Icon name="x" size={18} />
      </button>
      {children}
      {!hideCollapse && (
        <button
          type="button"
          className="pxui-sidebar-collapse"
          aria-label={collapsed ? "Zijbalk uitklappen" : "Zijbalk inklappen"}
          onClick={() => setCollapsed(!collapsed)}
        >
          <Icon name={collapsed ? "chevronsRight" : "chevronsLeft"} size={17} />
          <span className="pxui-sidebar-label">Inklappen</span>
        </button>
      )}
    </aside>
  );
});

export interface SidebarBrandProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Logo of merkteken links. */
  logo?: React.ReactNode;
  name: React.ReactNode;
  subtitle?: React.ReactNode;
}

export const SidebarBrand = React.forwardRef<HTMLDivElement, SidebarBrandProps>(function SidebarBrand(
  { logo, name, subtitle, className, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("pxui-sidebar-brand", className)} {...rest}>
      {logo && <span className="pxui-sidebar-mark">{logo}</span>}
      <span className="pxui-sidebar-brand-text pxui-sidebar-label">
        <span className="pxui-sidebar-brand-name">{name}</span>
        {subtitle && <span className="pxui-sidebar-brand-sub">{subtitle}</span>}
      </span>
    </div>
  );
});

export const SidebarNav = React.forwardRef<HTMLElement, React.HTMLAttributes<HTMLElement>>(
  function SidebarNav({ className, ...rest }, ref) {
    return <nav ref={ref} className={cn("pxui-sidebar-nav", className)} {...rest} />;
  }
);

export const SidebarSection = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function SidebarSection({ className, children, ...rest }, ref) {
    return (
      <div ref={ref} className={cn("pxui-sidebar-section pxui-sidebar-label", className)} {...rest}>
        {children}
      </div>
    );
  }
);

export interface SidebarItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  active?: boolean;
  /** Telling of status rechts. */
  badge?: React.ReactNode;
  asChild?: boolean;
}

export const SidebarItem = React.forwardRef<HTMLButtonElement, SidebarItemProps>(function SidebarItem(
  { icon, active, badge, asChild, className, children, ...rest },
  ref
) {
  const Comp = (asChild ? Slot : "button") as React.ElementType;

  return (
    <Comp
      ref={ref}
      type={asChild ? undefined : "button"}
      aria-current={active ? "page" : undefined}
      data-active={active ? "" : undefined}
      className={cn("pxui-sidebar-item", className)}
      {...rest}
    >
      {icon && <span className="pxui-sidebar-item-icon">{icon}</span>}
      <span className="pxui-sidebar-item-label pxui-sidebar-label">{children}</span>
      {badge !== undefined && <span className="pxui-sidebar-item-badge pxui-sidebar-label">{badge}</span>}
    </Comp>
  );
});

export const SidebarFooter = React.forwardRef<HTMLDivElement, React.HTMLAttributes<HTMLDivElement>>(
  function SidebarFooter({ className, ...rest }, ref) {
    return <div ref={ref} className={cn("pxui-sidebar-footer", className)} {...rest} />;
  }
);

/* ============================ Sidebar ============================ */
.pxui-sidebar {
  --pxui-rail-w: var(--sidebar-w);
  width: var(--pxui-rail-w); flex: none;
  background: var(--surface); border-right: 1px solid var(--border);
  display: flex; flex-direction: column; gap: 4px;
  padding: 16px 12px; position: sticky; top: 0; height: 100vh;
  overflow-x: hidden; overflow-y: auto;
  transition: width .22s var(--ease);
}
.pxui-sidebar[data-collapsed] { --pxui-rail-w: 76px; }
.pxui-sidebar[data-collapsed] .pxui-sidebar-label { opacity: 0; pointer-events: none; }
.pxui-sidebar[data-collapsed] .pxui-sidebar-section { height: 0; padding-top: 0; padding-bottom: 0; }

.pxui-sidebar-label { opacity: 1; transition: opacity .14s var(--ease); white-space: nowrap; }

.pxui-sidebar-brand { display: flex; align-items: center; gap: 11px; padding: 4px 6px 12px; }
.pxui-sidebar-mark {
  display: grid; place-items: center; width: 40px; height: 40px; flex: none;
  border-radius: var(--r-md); background: var(--accent); color: var(--accent-fg);
  box-shadow: var(--sh-sm); font-weight: 700;
}
.pxui-sidebar-mark svg { width: 22px; height: 22px; }
.pxui-sidebar-brand-text { display: flex; flex-direction: column; min-width: 0; }
.pxui-sidebar-brand-name { font-weight: 700; font-size: 16.5px; letter-spacing: -0.02em; color: var(--text); line-height: 1.05; }
.pxui-sidebar-brand-sub {
  font-size: 10.5px; font-weight: 600; letter-spacing: .07em;
  text-transform: uppercase; color: var(--text-3); margin-top: 2px;
}

.pxui-sidebar-nav { display: flex; flex-direction: column; gap: 4px; }
.pxui-sidebar-section {
  font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase;
  color: var(--text-3); padding: 14px 12px 6px; overflow: hidden;
  transition: opacity .14s var(--ease), height var(--dur) var(--ease), padding var(--dur) var(--ease);
}

.pxui-sidebar-item {
  position: relative; display: flex; align-items: center; gap: 12px;
  height: 44px; padding: 0 12px; width: 100%;
  border: none; background: transparent; border-radius: var(--r-md);
  color: var(--text-2); font: inherit; font-size: var(--fs-base); font-weight: 550;
  cursor: pointer; text-align: left; text-decoration: none;
  transition: background var(--dur-fast), color var(--dur-fast);
}
.pxui-sidebar-item-icon { display: inline-flex; flex: none; }
.pxui-sidebar-item-icon svg { width: 20px; height: 20px; }
.pxui-sidebar-item:hover { background: var(--surface-3); color: var(--text); }
.pxui-sidebar-item:focus-visible { outline: none; box-shadow: var(--ring); }
.pxui-sidebar-item[data-active] { background: var(--accent-tint); color: var(--accent-active); font-weight: 600; }
.pxui-sidebar-item[data-active] .pxui-sidebar-item-icon { color: var(--accent); }
.pxui-sidebar-item[data-active]::before {
  content: ""; position: absolute; left: -12px; top: 9px; bottom: 9px;
  width: 3px; background: var(--accent); border-radius: 0 3px 3px 0;
}
.pxui-sidebar-item-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.pxui-sidebar-item-badge {
  flex: none; display: inline-grid; place-items: center;
  min-width: 20px; height: 20px; padding: 0 6px; border-radius: var(--r-full);
  font-size: 11px; font-weight: 700; background: var(--surface-3); color: var(--text-2);
}
.pxui-sidebar-item:hover .pxui-sidebar-item-badge { background: var(--surface); }
.pxui-sidebar-item[data-active] .pxui-sidebar-item-badge { background: var(--accent-border); color: var(--accent-active); }

.pxui-sidebar-footer { margin-top: auto; padding-top: 8px; display: flex; flex-direction: column; gap: 4px; }

.pxui-sidebar-collapse {
  display: flex; align-items: center; gap: 12px; height: 40px; padding: 0 12px;
  border: none; background: transparent; border-radius: var(--r-md);
  color: var(--text-3); font: inherit; font-size: 13px; font-weight: 550;
  cursor: pointer; margin-top: 6px;
}
.pxui-sidebar-collapse:hover { background: var(--surface-3); color: var(--text); }
.pxui-sidebar-collapse svg { flex: none; }

.pxui-sidebar-mobile-close { display: none; }

@media (max-width: 860px) {
  .pxui-sidebar {
    --pxui-rail-w: min(82vw, 300px);
    position: fixed; top: 0; left: 0; height: 100dvh; z-index: var(--z-drawer);
    transform: translateX(-100%); transition: transform .26s var(--ease);
    box-shadow: var(--sh-xl);
  }
  .pxui-sidebar[data-collapsed] { --pxui-rail-w: min(82vw, 300px); }
  .pxui-sidebar[data-collapsed] .pxui-sidebar-label { opacity: 1; pointer-events: auto; }
  .pxui-sidebar[data-collapsed] .pxui-sidebar-section { height: auto; padding: 14px 12px 6px; }
  .pxui-sidebar-open { transform: none; }
  .pxui-sidebar-collapse { display: none; }
  .pxui-sidebar-mobile-close {
    display: grid; place-items: center; position: absolute; top: 14px; right: 12px;
    width: 34px; height: 34px; border: none; background: transparent;
    color: var(--text-3); border-radius: var(--r-sm); cursor: pointer;
  }
  .pxui-sidebar-mobile-close:hover { background: var(--surface-3); color: var(--text); }
}

/* ---------- Donkere variant (tone="inverted") ---------- */
.pxui-sidebar[data-tone="inverted"] {
  background: var(--sidebar-ink);
  border-right-color: var(--sidebar-ink-border);
  color: var(--sidebar-ink-text);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-brand-name { color: var(--sidebar-ink-strong); }
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-brand-sub,
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-section { color: var(--sidebar-ink-dim); }

.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-item { color: var(--sidebar-ink-text); }
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-item:hover {
  background: var(--sidebar-ink-hover); color: var(--sidebar-ink-strong);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-item[data-active] {
  background: var(--sidebar-ink-active); color: var(--sidebar-ink-accent);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-item[data-active] .pxui-sidebar-item-icon {
  color: var(--sidebar-ink-accent);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-item[data-active]::before {
  background: var(--sidebar-ink-accent);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-item-badge {
  background: var(--sidebar-ink-hover); color: var(--sidebar-ink-text);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-item[data-active] .pxui-sidebar-item-badge {
  background: var(--sidebar-ink-active); color: var(--sidebar-ink-accent);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-collapse,
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-mobile-close { color: var(--sidebar-ink-dim); }
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-collapse:hover,
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-mobile-close:hover {
  background: var(--sidebar-ink-hover); color: var(--sidebar-ink-strong);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-footer { border-top: 1px solid var(--sidebar-ink-border); }

/* Een blokje binnen de donkere rail, bv. een locatiekiezer of profielkaart. */
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-panel {
  display: flex; align-items: center; gap: 9px; width: 100%;
  padding: 9px 10px; margin-bottom: 10px;
  border: none; border-radius: var(--r-md);
  background: var(--sidebar-ink-hover); color: var(--sidebar-ink-strong);
  font: inherit; font-size: 13px; text-align: left; cursor: pointer;
  transition: background var(--dur-fast);
}
.pxui-sidebar[data-tone="inverted"] .pxui-sidebar-panel:hover { background: var(--sidebar-ink-active); }
.pxui-sidebar-panel-title { display: block; font-size: 12px; font-weight: 650; line-height: 1.2; }
.pxui-sidebar-panel-sub {
  display: block; font-size: 10.5px; color: var(--sidebar-ink-dim); line-height: 1.2;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
